import 'package:cloud_firestore/cloud_firestore.dart';
class RecommendationModel { const RecommendationModel({required this.id,required this.studentId,required this.majorId,required this.matchPercentage,required this.reasons,required this.createdAt,this.strengths=const [],this.weaknesses=const []}); final String id,studentId,majorId; final double matchPercentage; final List<String> reasons,strengths,weaknesses; final DateTime createdAt; factory RecommendationModel.fromFirestore(DocumentSnapshot<Map<String,dynamic>> doc)=>RecommendationModel.fromMap(doc.id,doc.data() ?? const {}); factory RecommendationModel.fromMap(String id,Map<String,dynamic> map)=>RecommendationModel(id:id,studentId:map['studentId'] as String? ?? '',majorId:map['majorId'] as String? ?? '',matchPercentage:(map['matchPercentage'] as num?)?.toDouble() ?? 0,reasons:List<String>.from(map['reasons'] as List? ?? const []),strengths:List<String>.from(map['strengths'] as List? ?? const []),weaknesses:List<String>.from(map['weaknesses'] as List? ?? const []),createdAt:(map['createdAt'] as Timestamp?)?.toDate() ?? DateTime.now()); Map<String,Object?> toMap()=>{'studentId':studentId,'majorId':majorId,'matchPercentage':matchPercentage,'reasons':reasons,'strengths':strengths,'weaknesses':weaknesses,'createdAt':Timestamp.fromDate(createdAt)}; }
